func TestImportRejectsCommentParentCyclesAtomically(t *testing.T) {
	for _, self := range []bool{false, true} {
		s := fixture(t)
		a := rec("comment", comment, "first")
		b := rec("comment", issue, "second")
		b.Issue = a.ID
		if self {
