func TestVerifiedSQLiteStoreStillRejectsAMismatchedStore(t *testing.T) {
	good := newMemoStoreFixture(t, 3, 2)
	if err := verifiedSQLiteStore(good, 3, 2); err != nil {
		t.Fatalf("a store matching its manifest was rejected: %v", err)
	}
