		return "", fmt.Errorf("distill: ollama url must be loopback-only: %s", endpoint)
	}
	body, err := json.Marshal(map[string]any{
		"model":  model,
		"system": args[2],
		"prompt": string(input),
		"stream": false,
	})
	if err != nil {
		return "", err
	}
	runCtx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()
